  #[using="AL IMG ALWF CSOKf CSmono_u CSmono_f ASB GSB GC GT GCTX GSEP CST CSCTX CSRI KL LEDGER_U TU_commit TU_fresh LEDGER_F TF_commit TF_fresh GMU GMFA CSUz CSFz ROOM_U SCAR_U ROOM_F SCAR_F"] Lemma getfrom_split : forall (TA TB : TSet)
      (ra gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (exb : bv 8)
      (j1 j2 j3 stw : word) (fa js0 ds shU shF : list _)
      (SP : Z) (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model) (CH n au nf lo : Z),
      let cs := class_size c in
      nf < n -> mu < au + cs * (n - nf) -> mu + 2^18 <= 0xE0000000 ->
      1 <= n <= 8 -> cs * n <= 2^18 -> 0 <= au <= mu -> mu - au <= 2^19 -> au mod 16 = 0 ->
      0 <= nf -> 4 * nf <= mfa -> 4 * (nf + 2^14) + 2^18 <= 2^29 -> Z.of_nat (length fa) = nf -> 4 * (nf + Z.of_nat (length js0)) = mfa ->
      length ds = 16%nat -> Pimg CH 64 -> CH + 64 <= T + 2768 -> T + 208 <= CH -> CH mod 4 = 0 ->
      crange (CSf None None) FA mfa ->
      rw_cells asegs m R [C8 (Z_to_bv 64 0)] ->
      rw_cells asegs m (R + 16) [C8 (Z_to_bv 64 nf)] -> rw_cells asegs m (R + 24) [C8 (Z_to_bv 64 mfa)] ->
      rw_cells asegs m (R + 32) [C8 (Z_to_bv 64 au)] -> rw_cells asegs m (R + 40) [C8 (Z_to_bv 64 0)] ->
      rw_cells asegs m (R + 48) [C8 (Z_to_bv 64 mu)] -> rw_cells asegs m (R + 56) [C8 (Z_to_bv 64 0)] ->
      rw_cells asegs m (R + 68) [C1 exb] -> rw_cells asegs m (R + 72) [C8 stw] ->
      rw_cells asegs m (T + 2872) [C8 j1; C8 j2] -> rw_cells asegs m (T + 2792) [C8 j3] ->
      rw_cells asegs m (0x7fff8000 + UA / 8) [CB (Z.to_nat 32768) shU] ->
      rw_cells asegs m (0x7fff8000 + FAA / 8) [CB (Z.to_nat 32768) shF] ->
      u32arr asegs m FA fa -> u32arr asegs m (FA + 4 * nf) js0 -> u32arr asegs m CH ds ->
      poison_statics m -> thr_statics m CTX T -> mwc_statics m -> pop_statics m SB -> ro_cells asegs m (A_INSTANCE + 48) [C8 (Z_to_bv 64 RI)] ->
      stk asegs m lo SP -> ACEIL <= lo -> lo <= SP - 1728 -> SP <= 2^63 -> SP mod 16 = 0 ->
      crange (CSf None None) lo (SP - lo) -> mem_inv asegs m -> tp = Z_to_bv 64 A_TP ->
      K None None mo -> J m mo ->
      TA [] -> TB [] ->
      (forall ok c', gf_cpostS ok SP gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra F fc CH n au nf lo exb fa js0 ds shU shF m c' -> srealizesJ asegs c' (if ok then TB else TA)) ->
