    assert (PPS1 : pop_statics m1 SB) by (eapply pop_statics_transport; [split; [exact PP1| split; [exact PP2| exact PP3]]| exact MU1| intros A k0 H; apply DJ1; unfold R; clear - H LOIMG SB0 HRI GC; lia]).
